-- Short shopping-centre / mall descriptions (shopping_centers.description),
-- hand-written from web research 2026-09-07: one or two sentences each —
-- what the centre is, where it sits, its anchor(s) and who it serves.
-- A few specifics (store counts, sizes, opening years) are approximate and
-- flagged in prose ("around", "roughly"). Requires migration 0019.

UPDATE shopping_centers SET description = 'A compact convenience centre on the corner of Grobler and Hans van Rensburg Streets in the Polokwane CBD, anchored by a Checkers supermarket with everyday shops and services alongside.' WHERE slug = 'checkers-centre-polokwane-central';

UPDATE shopping_centers SET description = 'A neighbourhood convenience centre on the corner of Outspan Drive and General Maritz Street in Bendor Park, next to the Cycad Estate. Managed by the Moolman Group, it covers groceries, pharmacy, food and everyday services for the eastern suburbs.' WHERE slug = 'cycad-centre-bendor-park';

UPDATE shopping_centers SET description = 'A small local centre at 293 Marshall Street in Flora Park, serving the surrounding southern suburbs with a supermarket and a mix of convenience shops and services.' WHERE slug = 'flora-park-shopping-centre-flora-park';

UPDATE shopping_centers SET description = 'A CBD centre on the corner of Market and Hospital Streets in central Polokwane, anchored by a Game store.' WHERE slug = 'game-centre-polokwane-central';

UPDATE shopping_centers SET description = 'A neighbourhood centre on the corner of Marshall and Campbell Streets in Ivy Park, a few minutes from the CBD, with a supermarket and everyday convenience stores and services.' WHERE slug = 'ivy-park-centre-ivy-park';

UPDATE shopping_centers SET description = 'A city-centre centre on the corner of Grobler and Schoeman Streets, beside the Library Gardens park in central Polokwane.' WHERE slug = 'library-gardens-polokwane-central';

UPDATE shopping_centers SET description = 'A small retail centre at 16 Jorissen Street in central Polokwane.' WHERE slug = 'lighthouse-mall-polokwane-central';

UPDATE shopping_centers SET description = 'An enclosed mall in the heart of the Polokwane CBD, on the corner of Rissik and Market Streets, with a supermarket plus fashion and everyday retail on a single level.' WHERE slug = 'limpopo-mall-polokwane-central';

UPDATE shopping_centers SET description = 'A local centre on the corner of Nelson Mandela Drive and Madiba Park Crossing, serving the Madiba Park area of the Seshego township.' WHERE slug = 'madiba-park-shopping-centre-seshego';

UPDATE shopping_centers SET description = 'Polokwane''s largest shopping centre — a super-regional mall on the corner of the R81 and the N1 bypass in Bendor, opened in 2010, with well over 140 stores including national fashion, department, grocery and entertainment anchors. It draws shoppers from across Limpopo.' WHERE slug = 'mall-of-the-north-bendor';

UPDATE shopping_centers SET description = 'A fully enclosed regional mall at the busy R518/R579 intersection in Lebowakgomo, south of Polokwane — the main shopping destination for the town and the wider Lepelle-Nkumpi area.' WHERE slug = 'mall-lebo-lebowakgomo';

UPDATE shopping_centers SET description = 'An established shopping centre at the R518/R579 intersection in Lebowakgomo, serving the town alongside the nearby Mall@Lebo.' WHERE slug = 'metlife-plaza-lebowakgomo';

UPDATE shopping_centers SET description = 'A local centre opposite the Nirvana Civic Centre, serving the Nirvana and Superbia area on the western side of Polokwane.' WHERE slug = 'pmt-square-nirvana';

UPDATE shopping_centers SET description = 'The main mall for Mankweng and the University of Limpopo, on the R71 at Ga Thoka. Grown through several expansions from a small convenience centre to around 30,000 m² and roughly 90 stores, anchored by Shoprite, Spar and Woolworths.' WHERE slug = 'paledi-mall-mankweng';

UPDATE shopping_centers SET description = 'A convenience centre on the corner of Hans van Rensburg and Grobler Streets in the northern part of the Polokwane CBD, with a Checkers supermarket and everyday shops and services.' WHERE slug = 'palm-centre-moregloed';

UPDATE shopping_centers SET description = 'A retail and office park on Watermelon Street in Bendor Park, near the corner of Outspan Drive and General Maritz Street, mixing shops and restaurants with professional offices.' WHERE slug = 'platinum-park-bendor-park';

UPDATE shopping_centers SET description = 'A centre on the corner of Market Street and Landros Maré Street in central Polokwane.' WHERE slug = 'polokwane-lifestyle-centre-polokwane-central';

UPDATE shopping_centers SET description = 'A Polokwane landmark since it opened in 1997, on the corner of Thabo Mbeki Street (R71) and Grimm Street in Fauna Park. Around 90 stores anchored by Checkers, Pick n Pay, Woolworths, Clicks and Dis-Chem, with a cinema.' WHERE slug = 'savannah-mall-fauna-park';

UPDATE shopping_centers SET description = 'A mid-sized mall where Nelson Mandela Drive and Polokwane Drive meet — the two roads linking Seshego to the city. Roughly 35 shops plus a medical centre and banks, and the main retail hub for the Seshego township.' WHERE slug = 'seshego-circle-seshego';

UPDATE shopping_centers SET description = 'A community shopping centre on New Era Drive in Seshego, with a supermarket and everyday retail serving the township.' WHERE slug = 'seshego-plaza-seshego';

UPDATE shopping_centers SET description = 'A small centre on the corner of Grobler and Grimm Streets in Fauna Park, close to Savannah Mall.' WHERE slug = 'the-crossing-shopping-centre-fauna-park';

UPDATE shopping_centers SET description = 'A newer centre on the corner of Oost and Grobler Streets in central Polokwane, adding fresh retail and dining to the CBD.' WHERE slug = 'the-greenery-polokwane-central';

UPDATE shopping_centers SET description = 'A village-style centre of around 20 stores on the R81 (Munnik Avenue) at Thornhill, opened in 2009 and known for its natural-stone architecture. Anchored by SuperSpar, with Clicks and Sportsmans Warehouse among the tenants.' WHERE slug = 'thornhill-shopping-centre-thornhill-estate';

UPDATE shopping_centers SET description = 'A shopping centre on the corner of University Road and Mankweng Street, serving University of Limpopo students and the surrounding Mankweng community.' WHERE slug = 'turfloop-plaza-mankweng';
